SELECT DISTINCT ?a ?aLabel ?b ?bLabel ?proj ?projLabel ?paper ?paperLabel ?countryA ?countryALabel ?countryB ?countryBLabel WHERE {
  ?a ex:collaboratesWith ?b .
  ?a ex:worksAt ?labA .
  ?labA ex:locatedIn ?cityA .
  ?cityA ex:country ?countryA .
  ?b ex:worksAt ?labB .
  ?labB ex:locatedIn ?cityB .
  ?cityB ex:country ?countryB .
  FILTER(?countryA != ?countryB)
  ?a (ex:participatesIn|ex:leads) ?proj .
  ?b (ex:participatesIn|ex:leads) ?proj .
  ?a ex:authored ?paper .
  ?b ex:authored ?paper .
  ?paper ex:status ex:published .
  OPTIONAL { ?a rdfs:label ?aLabel }
  OPTIONAL { ?b rdfs:label ?bLabel }
  OPTIONAL { ?proj rdfs:label ?projLabel }
  OPTIONAL { ?paper rdfs:label ?paperLabel }
  OPTIONAL { ?countryA rdfs:label ?countryALabel }
  OPTIONAL { ?countryB rdfs:label ?countryBLabel }
}
ORDER BY ?aLabel ?bLabel ?projLabel ?paperLabel

SELECT DISTINCT ?person ?personLabel WHERE {
  ?person <https://spinach.local/worksAt> ?lab .
  ?lab <https://spinach.local/locatedIn> ?city .
  ?city <https://spinach.local/country> <https://spinach.local/country1> .
  ?person <https://spinach.local/leads> ?proj .
  ?proj <https://spinach.local/topic> <https://spinach.local/topic3> .
  FILTER NOT EXISTS {
    ?person <https://spinach.local/authored> ?paper .
    ?paper <https://spinach.local/status> <https://spinach.local/retracted> .
  }
  OPTIONAL { ?person rdfs:label ?personLabel }
}
ORDER BY ?personLabel

SELECT DISTINCT ?a ?aLabel ?b ?bLabel ?proj ?projLabel ?paper ?paperLabel ?countryALabel ?countryBLabel WHERE {
  # Collaboration in either direction
  { ?a <https://spinach.local/collaboratesWith> ?b }
  UNION
  { ?b <https://spinach.local/collaboratesWith> ?a } .
  FILTER(?a != ?b)

  # Countries via institutions -> cities -> countries
  ?a <https://spinach.local/worksAt> ?labA .
  ?b <https://spinach.local/worksAt> ?labB .
  ?labA <https://spinach.local/locatedIn> ?cityA .
  ?labB <https://spinach.local/locatedIn> ?cityB .
  ?cityA <https://spinach.local/country> ?countryA .
  ?cityB <https://spinach.local/country> ?countryB .
  FILTER(?countryA != ?countryB)

  # Shared project (either leads or participates)
  { { ?a <https://spinach.local/participatesIn> ?proj } UNION { ?a <https://spinach.local/leads> ?proj } }
  { { ?b <https://spinach.local/participatesIn> ?proj } UNION { ?b <https://spinach.local/leads> ?proj } }

  # Coauthored a published paper together
  ?a <https://spinach.local/authored> ?paper .
  ?b <https://spinach.local/authored> ?paper .
  ?paper <https://spinach.local/status> <https://spinach.local/published> .

  OPTIONAL { ?a <http://www.w3.org/2000/01/rdf-schema#label> ?aLabel }
  OPTIONAL { ?b <http://www.w3.org/2000/01/rdf-schema#label> ?bLabel }
  OPTIONAL { ?proj <http://www.w3.org/2000/01/rdf-schema#label> ?projLabel }
  OPTIONAL { ?paper <http://www.w3.org/2000/01/rdf-schema#label> ?paperLabel }
  OPTIONAL { ?countryA <http://www.w3.org/2000/01/rdf-schema#label> ?countryALabel }
  OPTIONAL { ?countryB <http://www.w3.org/2000/01/rdf-schema#label> ?countryBLabel }
}
ORDER BY ?a ?b ?proj ?paper

SELECT DISTINCT ?a ?aLabel ?b ?bLabel WHERE {
  { ?a <https://spinach.local/collaboratesWith> ?b }
  UNION
  { ?b <https://spinach.local/collaboratesWith> ?a } .
  FILTER(?a != ?b)
  FILTER(STR(?a) < STR(?b))

  FILTER EXISTS {
    ?a <https://spinach.local/worksAt> ?labA .
    ?b <https://spinach.local/worksAt> ?labB .
    ?labA <https://spinach.local/locatedIn> ?cityA .
    ?labB <https://spinach.local/locatedIn> ?cityB .
    ?cityA <https://spinach.local/country> ?countryA .
    ?cityB <https://spinach.local/country> ?countryB .
    FILTER(?countryA != ?countryB)
  }

  FILTER EXISTS {
    { ?a <https://spinach.local/participatesIn> ?proj } UNION { ?a <https://spinach.local/leads> ?proj } .
    { ?b <https://spinach.local/participatesIn> ?proj } UNION { ?b <https://spinach.local/leads> ?proj } .
  }

  FILTER EXISTS {
    ?a <https://spinach.local/authored> ?paper .
    ?b <https://spinach.local/authored> ?paper .
    ?paper <https://spinach.local/status> <https://spinach.local/published> .
  }

  OPTIONAL { ?a <http://www.w3.org/2000/01/rdf-schema#label> ?aLabel }
  OPTIONAL { ?b <http://www.w3.org/2000/01/rdf-schema#label> ?bLabel }
}
ORDER BY ?a ?b

SELECT DISTINCT ?a ?aLabel ?b ?bLabel ?proj ?projLabel ?paper ?paperLabel ?countryALabel ?countryBLabel WHERE {
  { ?a <https://spinach.local/collaboratesWith> ?b }
  UNION
  { ?b <https://spinach.local/collaboratesWith> ?a } .
  FILTER(?a != ?b)
  FILTER(STR(?a) < STR(?b))

  ?a <https://spinach.local/worksAt> ?labA .
  ?b <https://spinach.local/worksAt> ?labB .
  ?labA <https://spinach.local/locatedIn> ?cityA .
  ?labB <https://spinach.local/locatedIn> ?cityB .
  ?cityA <https://spinach.local/country> ?countryA .
  ?cityB <https://spinach.local/country> ?countryB .
  FILTER(?countryA != ?countryB)

  ?a (<https://spinach.local/participatesIn>|<https://spinach.local/leads>) ?proj .
  ?b (<https://spinach.local/participatesIn>|<https://spinach.local/leads>) ?proj .

  ?a <https://spinach.local/authored> ?paper .
  ?b <https://spinach.local/authored> ?paper .
  ?paper <https://spinach.local/status> <https://spinach.local/published> .

  OPTIONAL { ?a rdfs:label ?aLabel }
  OPTIONAL { ?b rdfs:label ?bLabel }
  OPTIONAL { ?proj rdfs:label ?projLabel }
  OPTIONAL { ?paper rdfs:label ?paperLabel }
  OPTIONAL { ?countryA rdfs:label ?countryALabel }
  OPTIONAL { ?countryB rdfs:label ?countryBLabel }
}
ORDER BY ?a ?b ?proj ?paper

SELECT DISTINCT ?a ?aLabel ?b ?bLabel ?proj ?projLabel ?paper ?paperLabel ?countryALabel ?countryBLabel WHERE {
  { ?a ex:collaboratesWith ?b } UNION { ?b ex:collaboratesWith ?a }
  FILTER(?a != ?b)
