  { ?b ex:participatesIn ?proj } UNION { ?b ex:leads ?proj }

  ?a ex:authored ?paper .
  ?b ex:authored ?paper .
  ?paper ex:status ex:published .

  OPTIONAL { ?a rdfs:label ?aLabel }
  OPTIONAL { ?b rdfs:label ?bLabel }
  OPTIONAL { ?proj rdfs:label ?projLabel }
  OPTIONAL { ?paper rdfs:label ?paperLabel }
  OPTIONAL { ?countryA rdfs:label ?countryALabel }
  OPTIONAL { ?countryB rdfs:label ?countryBLabel }
}
ORDER BY ?a ?b ?proj ?paper

SELECT DISTINCT ?person ?personLabel WHERE {
  ?person <https://spinach.local/worksAt> ?inst .
  ?inst <https://spinach.local/locatedIn> ?city .
  ?city <https://spinach.local/country> <https://spinach.local/country1> .
  ?person <https://spinach.local/leads> ?proj .
  ?proj <https://spinach.local/topic> <https://spinach.local/topic3> .
  FILTER NOT EXISTS {
    ?person <https://spinach.local/authored> ?paper .
    ?paper <https://spinach.local/status> <https://spinach.local/retracted> .
  }
  OPTIONAL { ?person rdfs:label ?personLabel }
}
ORDER BY ?personLabel ?person

PREFIX ex: <https://spinach.local/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?project ?projectLabel ?total WHERE {
  {
    SELECT ?project (SUM(?cit) AS ?total) WHERE {
      SELECT DISTINCT ?project ?paper (xsd:integer(?c) AS ?cit) WHERE {
        ?paper ex:status ex:published .
        ?paper ex:aboutProject ?project .
        ?author ex:authored ?paper .
        ?author ex:worksAt ?lab .
        ?lab ex:locatedIn ?city .
        ?city ex:country ex:country0 .
        ?paper ex:citations ?c .
      }
    }
    GROUP BY ?project
  }
  OPTIONAL { ?project rdfs:label ?projectLabel }
  {
    SELECT (MAX(?total) AS ?maxTotal) WHERE {
      SELECT ?project (SUM(?cit) AS ?total) WHERE {
        SELECT DISTINCT ?project ?paper (xsd:integer(?c) AS ?cit) WHERE {
          ?paper ex:status ex:published .
          ?paper ex:aboutProject ?project .
          ?author ex:authored ?paper .
          ?author ex:worksAt ?lab .
          ?lab ex:locatedIn ?city .
          ?city ex:country ex:country0 .
          ?paper ex:citations ?c .
        }
      }
      GROUP BY ?project
    }
  }
  FILTER(?total = ?maxTotal)
}
ORDER BY COALESCE(?projectLabel, STR(?project))

PREFIX ex: <https://spinach.local/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

# Projects with total citations from published papers that have at least one author in France
SELECT ?project ?total WHERE {
  {
    SELECT ?project (SUM(?c) AS ?total)
    WHERE {
      {
        SELECT DISTINCT ?paper ?project ?c
        WHERE {
          ?paper ex:status ex:published .
          ?paper ex:aboutProject ?project .
          ?paper ex:citations ?cLit .
          BIND(xsd:integer(?cLit) AS ?c)
          FILTER(isNumeric(?c))
          EXISTS {
            ?author ex:authored ?paper .
            ?author ex:worksAt ?inst .
            ?inst ex:locatedIn ?city .
            ?city ex:country ex:country0 . # France
          }
        }
      }
    }
    GROUP BY ?project
  }
  {
    SELECT (MAX(?total2) AS ?maxTotal)
    WHERE {
      {
        SELECT ?project2 (SUM(?c2) AS ?total2)
        WHERE {
          {
            SELECT DISTINCT ?paper2 ?project2 ?c2
            WHERE {
              ?paper2 ex:status ex:published .
              ?paper2 ex:aboutProject ?project2 .
              ?paper2 ex:citations ?cLit2 .
              BIND(xsd:integer(?cLit2) AS ?c2)
              FILTER(isNumeric(?c2))
              EXISTS {
                ?author2 ex:authored ?paper2 .
                ?author2 ex:worksAt ?inst2 .
                ?inst2 ex:locatedIn ?city2 .
                ?city2 ex:country ex:country0 .
              }
            }
          }
        }
        GROUP BY ?project2
      }
    }
  }
  FILTER(?total = ?maxTotal)
}
ORDER BY ?project

PREFIX ex: <https://spinach.local/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

# Projects with total citations from published papers that have at least one author affiliated in France; each paper counted once
SELECT ?project ?total WHERE {
  {
    SELECT ?project (SUM(?c) AS ?total)
    WHERE {
      {
        SELECT DISTINCT ?paper ?project (xsd:integer(?cLit) AS ?c)
        WHERE {
          ?paper ex:status ex:published .
          ?paper ex:aboutProject ?project .
          ?paper ex:citations ?cLit .
          ?author ex:authored ?paper .
          ?author ex:worksAt ?inst .
          ?inst ex:locatedIn ?city .
          ?city ex:country ex:country0 .
        }
      }
    }
    GROUP BY ?project
  }
  {
    SELECT (MAX(?total2) AS ?maxTotal)
    WHERE {
      {
        SELECT ?project2 (SUM(?c2) AS ?total2)
        WHERE {
          {
            SELECT DISTINCT ?paper2 ?project2 (xsd:integer(?cLit2) AS ?c2)
            WHERE {
              ?paper2 ex:status ex:published .
              ?paper2 ex:aboutProject ?project2 .
              ?paper2 ex:citations ?cLit2 .
              ?author2 ex:authored ?paper2 .
              ?author2 ex:worksAt ?inst2 .
              ?inst2 ex:locatedIn ?city2 .
              ?city2 ex:country ex:country0 .
            }
          }
        }
        GROUP BY ?project2
      }
    }
  }
  FILTER(?total = ?maxTotal)
}
ORDER BY ?project

SELECT DISTINCT ?project ?researcher WHERE {
  ?project ex:topic ex:topic0 .
  ?project ex:fundedBy ex:funder0 .
  { ?researcher ex:participatesIn ?project }
  UNION
  { ?researcher ex:leads ?project }
  ?researcher ex:worksAt ?inst .
  ?inst ex:locatedIn ?city .
  ?city ex:country ex:country0 .
} ORDER BY ?project ?researcher

SELECT DISTINCT ?project ?projectLabel ?person ?personLabel WHERE {
  ?project <https://spinach.local/topic> <https://spinach.local/topic0> .
  ?project <https://spinach.local/fundedBy> <https://spinach.local/funder0> .
  { ?person <https://spinach.local/leads> ?project }
  UNION
  { ?person <https://spinach.local/participatesIn> ?project } .
  ?person <https://spinach.local/worksAt> ?inst .
  ?inst <https://spinach.local/locatedIn> ?city .
  ?city <https://spinach.local/country> <https://spinach.local/country0> .
  OPTIONAL { ?project <http://www.w3.org/2000/01/rdf-schema#label> ?projectLabel }
  OPTIONAL { ?person  <http://www.w3.org/2000/01/rdf-schema#label> ?personLabel }
}
ORDER BY ?projectLabel ?personLabel

SELECT DISTINCT ?project ?projectLabel ?person ?personLabel WHERE {
  ?project ex:topic ex:topic0 ;
           ex:fundedBy ex:funder0 .
  {
    ?person ex:leads ?project .
  }
  UNION
  {
    ?person ex:participatesIn ?project .
  }
  ?person ex:worksAt ?inst .
  ?inst ex:locatedIn ?city .
  ?city ex:country ex:country0 .
  OPTIONAL { ?project rdfs:label ?projectLabel }
  OPTIONAL { ?person rdfs:label ?personLabel }
}
ORDER BY ?projectLabel ?personLabel

SELECT ?project (SAMPLE(?label) AS ?projectLabel) (COUNT(DISTINCT ?country) AS ?countryCount)
WHERE {
  {
    SELECT DISTINCT ?project ?person WHERE {
      { ?person ex:participatesIn ?project . }
      UNION
      { ?person ex:leads ?project . }
    }
  }
  ?person ex:worksAt ?inst .
  ?inst ex:locatedIn ?city .
  ?city ex:country ?country .
  OPTIONAL { ?project rdfs:label ?label }
}
GROUP BY ?project
HAVING (COUNT(DISTINCT ?country) >= 2)
ORDER BY ?projectLabel

PREFIX ex: <https://spinach.local/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?inst ?inst_label WHERE {
  ?inst ex:partnersWith+ ex:lab7 .
  ?person ex:worksAt ?inst .
  ?person ex:leads ?proj .
  ?proj ex:topic ex:topic0 .
  OPTIONAL { ?inst rdfs:label ?inst_label }
}
ORDER BY ?inst_label ?inst

PREFIX ex: <https://spinach.local/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?inst ?instLabel WHERE {
  ?inst ex:partnersWith+ ex:lab7 .
  ?person ex:worksAt ?inst .
  ?person ex:leads ?proj .
  ?proj ex:topic ex:topic0 .
  OPTIONAL { ?inst rdfs:label ?instLabel }
}
ORDER BY COALESCE(?instLabel, STR(?inst))
